#include <stdio.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
void handle_pipe(int sig) {
  fprintf(stderr, "SIGPIPE received, continuing...
");
  errno = 0; //reset errno to avoid further issues
}
int main() {
  signal(SIGPIPE, handle_pipe);
  int fd = open("my_file.txt", O_WRONLY | O_CREAT, 0644);
  if (fd == -1) { perror("open"); return 1; }
  char *message = "This is a test message\n";
  ssize_t bytes_written = write(fd, message, strlen(message));
  if (bytes_written == -1) { perror("write"); }
  close(fd);
  return 0;
}
